package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;
import java.util.Objects;

/** A version of the sheet's policy: the change to one of its policy settings (see
 *  {@link Sheet#POLICY_KEYS}) that made it, numbered from 1 in the order made, with the from-date
 *  the changed value is in force from (null: none, the version counts on every date). */
@Embeddable
public class PolicyVersion {

    @Column(name = "number", nullable = false)
    private int number;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date")
    private LocalDate from;

    protected PolicyVersion() {
    }

    public PolicyVersion(int number, String key, LocalDate from) {
        this.number = number;
        this.key = key;
        this.from = from;
    }

    public int getNumber() {
        return number;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    /** Whether the version is in force on a date: it has no from-date, or one on or before it. */
    public boolean countsOn(LocalDate on) {
        return from == null || !from.isAfter(on);
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof PolicyVersion other && number == other.number && key.equals(other.key)
                && Objects.equals(from, other.from);
    }

    @Override
    public int hashCode() {
        return Objects.hash(number, key, from);
    }
}
    /** The sheet's clerk limit in force on its today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return sheets.find(sheetId).map(Sheet::getClerkLimit).orElse(null);
    }

    /** Set the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), the
     *  sheet created first if it was never loaded; the limit in force on the sheet's today applies. */
    @Transactional
    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        BigDecimal scaled = limit == null ? null : limit.setScale(2);
        record(sheet, user, CLERK_LIMIT, scaled == null ? "" : scaled.toPlainString(), from);
        return scaled;
    }

    /** Set a grade's clerk limit (null: none, the grade uses the sheet's) from a date (null: the
     *  sheet's today), the sheet created first if it was never loaded; a claim whose person's grade
     *  on the sheet's today is this one is held to it while it is in force then. */
    @Transactional
    public BigDecimal setGradeClerkLimit(String sheetId, String user, String grade, BigDecimal limit, LocalDate from) {
        sheets.requireGrade(sheetId, grade);
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        BigDecimal scaled = limit == null ? null : limit.setScale(2);
        record(sheet, user, CLERK_LIMIT_OF_GRADE + grade, scaled == null ? "" : scaled.toPlainString(), from);
        return scaled;
    }

    /** Record a dated setting's value (blank: none) from a date (null: the sheet's today), replacing
     *  one recorded from the same date, and audit it, with the from-date when one was given; a
     *  change to a policy setting is a new version of the policy, counted from the same date. */
    private void record(Sheet sheet, String user, String key, String value, LocalDate from) {
        LocalDate on = from != null ? from : sheet.getToday();
        sheet.recordSetting(key, on, value.isEmpty() ? null : value);
        if (Sheet.POLICY_KEYS.contains(key)) {
            sheet.recordPolicyVersion(key, on);
        }
        sheets.flush();
        history.recordSheet(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheet.getId() + " by=" + user
                + " key=" + key + " value=" + value + (from == null ? "" : " from=" + from));
    }

    /** The sheet's floor: a claim's live due is at least it. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return sheets.floor(sheetId);
    }

    /** Set the sheet's floor from a date (null: the sheet's today), the sheet created first if it
     *  was never loaded; every live due of a claim dated from then on to the next from-date (and so
     *  every total) moves with it, while settled, bound and closed figures stay as they are. */
    @Transactional
    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = floor.setScale(2);
        record(sheet, user, FLOOR, scaled.toPlainString(), from);
     *  none, the floor with two decimals, the terms in days, the late percent with two decimals,
     *  the policy date, null when blank, the period numbering from-date, null when blank (off),
     *  the terms each grade has of its own, a grade without them left out, the cap with two
     *  decimals, null for none, and the proof threshold with two decimals, null for none, the grace days, null when blank (off), the entry date, null when blank (off), the pot with two decimals, null for none, the alert threshold with two decimals, null for none, the month (1 to 12) the fiscal year starts in, each of the dated ones as in force on the sheet's today; and every
     *  value recorded for the dated settings, by key, each key's by from-date; and the permission
     *  matrix: the roles set for each action, comma separated, an action left blank left out; and the
     *  escalation gap in days, null when blank (off); and the review SLA in days, null when blank (none);
     *  and the mid and high score thresholds, each null when blank; and whether the score log is on;
     *  and the maximum of open claims per person, null when blank (none); and the pending SLA in
     *  days, null when blank (none). */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, String proofThreshold,
            Integer graceDays, LocalDate entryDate, String pot, String alertThreshold, int fiscalStartMonth, Map<String, List<DatedValue>> dated, Map<String, String> permissions,
            Integer escalateAfter, Integer reviewSla, Integer scoreMid, Integer scoreHigh, boolean scoreLog, Integer maxOpen,
            Integer pendingSla, List<LocalDate> policyVersions) {
        static SettingsView of(BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct, LocalDate policyDate,
                LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap, BigDecimal proofThreshold,
                Integer graceDays, LocalDate entryDate, BigDecimal pot, BigDecimal alertThreshold, int fiscalStartMonth, Map<String, List<DatedSetting>> dated, Map<Permission, String> permissions,
                Integer escalateAfter, Integer reviewSla, Integer scoreMid, Integer scoreHigh, boolean scoreLog, Integer maxOpen,
            Integer pendingSla, List<PolicyVersion> policyVersions) {
            Map<String, String> perms = new TreeMap<>();
            permissions.forEach((action, roles) -> perms.put(action.key(), roles));
            return new SettingsView(clerkLimit == null ? null : clerkLimit.toPlainString(), floor.toPlainString(), terms,
                    latePct.setScale(2).toPlainString(), policyDate, periodNumberingFrom, gradeTerms,
                    cap == null ? null : cap.setScale(2).toPlainString(),
                    proofThreshold == null ? null : proofThreshold.setScale(2).toPlainString(), graceDays, entryDate,
                    pot == null ? null : pot.setScale(2).toPlainString(),
                    alertThreshold == null ? null : alertThreshold.setScale(2).toPlainString(), fiscalStartMonth, DatedValue.of(dated), perms,
                    escalateAfter, reviewSla, scoreMid, scoreHigh, scoreLog, maxOpen, pendingSla,
                    policyVersionsOf(policyVersions));
        }
    }

    /** The from-date of each version of a sheet's policy, by number (null: none, counted on every date). */
    public static List<LocalDate> policyVersionsOf(List<PolicyVersion> versions) {
        return versions.stream().map(PolicyVersion::getFrom).toList();
    }

    /** A value recorded for a dated setting: in force from its from-date until the next one of its
     *  key; null for none. */
    public record DatedValue(LocalDate from, String value) {
        service.setPermission(sheetId, user.trim(), Permission.of(action), roles);
        return view(sheetId);
    }

    private SettingsView view(String sheetId) {
        return SettingsView.of(service.clerkLimit(sheetId), service.floor(sheetId), service.terms(sheetId),
                service.latePct(sheetId), service.policyDate(sheetId), service.periodNumberingFrom(sheetId),
                gradeTerms(sheetId), service.cap(sheetId), service.proofThreshold(sheetId), service.graceDays(sheetId), service.entryDate(sheetId), service.pot(sheetId), service.alertThreshold(sheetId), service.fiscalStartMonth(sheetId), service.datedSettings(sheetId),
                service.permissions(sheetId), service.escalateAfter(sheetId), service.reviewSla(sheetId),
                service.scoreMid(sheetId), service.scoreHigh(sheetId), service.scoreLog(sheetId), service.maxOpen(sheetId),
                service.pendingSla(sheetId), service.policyVersions(sheetId));
    }

    /** The settings as they stood at the end of a date, that date the sheet's today. */
    private static SettingsView viewAsOf(HistoryService.AsOf then) {
        Sheet sheet = then.sheet();
        Map<String, Integer> gradeTerms = new TreeMap<>();
        for (String grade : sheet.getGrades()) {
            Integer terms = sheet.getGradeTerms(grade);
            if (terms != null) {
                gradeTerms.put(grade, terms);
            }
        }
        return SettingsView.of(sheet.getClerkLimit(), sheet.getFloor(), sheet.getTerms(), sheet.getLatePct(),
                sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(), gradeTerms, sheet.getCap(),
                sheet.getProofThreshold(), sheet.getGraceDays(), sheet.getEntryDate(), sheet.getPot(), sheet.getAlertThreshold(), sheet.getFiscalStartMonth(), sheet.getDatedSettings(), then.permissions(),
                sheet.getEscalateAfter(), sheet.getReviewSla(), sheet.getScoreMid(), sheet.getScoreHigh(), sheet.isScoreLog(), sheet.getMaxOpen(),
                sheet.getPendingSla(), sheet.getPolicyVersions());
    }

    /** A from-date as the form submits it; null when blank or left out (the sheet's today). */
     *  separated (null when none); and its default grade (null when blank: A); and its retired grades, in the
     *  order retired; and its grades, A, B and C then those added in the order added; and the from-date
     *  of each version of its policy, by number (null: none, counted on every date). */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct, LocalDate policyDate,
            String cap, Map<String, List<DatedValue>> dated, boolean archived, String parent, String proofKinds,
            String defaultGrade, List<String> retiredGrades, List<String> grades, List<LocalDate> policyVersions) {
        static SheetView of(Sheet sheet) {
            return of(sheet, sheet.getParent(), sheet.getGrades());
        }

        static SheetView of(Sheet sheet, String parent, List<String> grades) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().setScale(2).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().setScale(2).toPlainString(),
                    DatedValue.of(sheet.getDatedSettings()), sheet.isArchived(), parent, sheet.getProofKinds(),
                    sheet.getDefaultGrade(), SettingsService.retiredGrades(sheet), grades,
                    SettingsController.policyVersionsOf(sheet.getPolicyVersions()));
        }
    }

    public record TodayChange(@NotNull LocalDate today) {

